CREATE OR REPLACE VIEW "EXT"."CSA_DETALLE_REPARTO_PAGOS_SVW" ( "PERIODO", "PERIODO_FORMATO", "NIF", "COD_UNICO", "COD_AGENTE", "MANAGER", "TIPO_AGENTE", "TIPO_PAGO", "CONCEPTO_PAGO", "GRUPO_PAGO", "IMPORTE", "NUM_TRAMO", "TIPO_REPARTO", "REPARTO_TIPO_BASE", "REPARTO_PORCENTAJE", "PRODUCTO", "CODIGO_POLIZA", "CODIGO_RECIBO", "PERMANENCIA", "POLIZA_FISICA", "POLIZA_CORREGIDA", "PRIMA_CORREGIDA", "PRIMA_NETA", "PRIMA_NETA_ANUAL", "PRIMA_COMIS", "COEF_TIPO_BASE", "COEF_CORRECTOR", "IMPORTE_REPARTO", "AGENCIA", "PERIODSEQ", "POSITIONSEQ" ) AS (SELECT "PERIODO" , "PERIODO_FORMATO" , "NIF" , "COD_UNICO" , "COD_AGENTE" , "MANAGER" , "TIPO_AGENTE" , "TIPO_PAGO" , "CONCEPTO_PAGO" , "GRUPO_PAGO" , "IMPORTE" , "NUM_TRAMO" , "TIPO_REPARTO" , "REPARTO_TIPO_BASE" , "REPARTO_PORCENTAJE" , "PRODUCTO" , "CODIGO_POLIZA" , "CODIGO_RECIBO" , "PERMANENCIA" , "POLIZA_FISICA" , "POLIZA_CORREGIDA" , "PRIMA_CORREGIDA" , "PRIMA_NETA" , "PRIMA_NETA_ANUAL" , "PRIMA_COMIS" , "COEF_TIPO_BASE" , "COEF_CORRECTOR" , "IMPORTE_REPARTO" , "AGENCIA" , "PERIODSEQ" , "POSITIONSEQ" 
	FROM EXT.OUT_DETALLE_REPARTO_PAGOS_FINAL_REP
	WHERE PERIODSEQ IN (SELECT PERIODSEQ from cs_period where startdate like'2026-%' and removedate= TO_DATE('2200-01-01','YYYY-MM-DD')));